/* COSC 407/507 Lab 4, core A -- k2, a parallel program that is correct and slow.
 *
 * *** DO NOT EDIT THIS FILE. *** It is hashed. Work in fix/k2.c.
 *
 * What it does: sorts n random 64-bit values into 4 bands by their top two
 * bits, and counts how many land in each band. It does that PASSES times over
 * the same values, so the run is long enough to time (the values fit in
 * cache, so what we time is the counting, not the memory).
 *
 * ---------------------------------------------------------------------------
 * What the author believed:
 *
 *   "Every thread counts into its OWN slot -- slot[t], where t is its thread
 *    number -- and main adds the slots up at the end. No two threads ever
 *    write the same variable, so there is no race, no lock and no atomic, and
 *    nothing for the threads to wait for. So it scales."
 *
 * Every statement in that paragraph is true except the last sentence.
 * ---------------------------------------------------------------------------
 *
 *   bin/k2 [threads] [n]          defaults: 4 threads, n = 32768
 *
 * It also prints how big one slot is and where slot[0] starts within a 64-byte
 * block of memory (offset=0 means it starts exactly on a 64-byte boundary).
 */
#include <stddef.h>
#include <stdint.h>

#include "lab4.h"

#define PASSES 6000

#ifndef PAD
#define PAD 0               /* tests/sweep.sh builds this with PAD=16, 48, ... */
#endif

typedef struct {
    int band[4];            /* counts for bands 0..3 */
#if PAD > 0
    char pad[PAD];          /* only in the sweep: makes each slot PAD bytes bigger */
#endif
} slot_t;

static slot_t slot[LAB4_MAX_THREADS];    /* slot[t] belongs to thread t */

void ref_k2(const uint64_t *x, long n, long passes, long out[4]);   /* src/ref.c */

int main(int argc, char **argv)
{
    lab4_args_t a = lab4_args(argc, argv, 32768);
    uint64_t *x = lab4_alloc((size_t)a.n * sizeof *x);
    int threads = a.threads > 0 ? a.threads : 1;

    double t0 = lab4_now();
    lab4_fill(x, a.n, 2026);
    double t1 = lab4_now();

    for (int t = 0; t < threads; t++)
        for (int b = 0; b < 4; b++)
            slot[t].band[b] = 0;

    #pragma omp parallel
    {
        int t = omp_get_thread_num();
        for (int p = 0; p < PASSES; p++) {
            /* nowait: no thread waits for the others at the end of a pass. Safe,
             * because every pass gives each thread the same slice of x. */
            #pragma omp for nowait
            for (long i = 0; i < a.n; i++) {
                slot[t].band[x[i] >> 62]++;        /* top two bits: 0..3 */
            }
        }
    }

    long total[4] = { 0, 0, 0, 0 };
    for (int t = 0; t < threads; t++)
        for (int b = 0; b < 4; b++)
            total[b] += slot[t].band[b];
    double t2 = lab4_now();

    long want[4];
    ref_k2(x, a.n, PASSES, want);
    int ok = total[0] == want[0] && total[1] == want[1] &&
             total[2] == want[2] && total[3] == want[3];

    printf("slot_bytes=%zu offset=%u  ", sizeof(slot_t),
           (unsigned)((uintptr_t)&slot[0] % 64));
    lab4_report("k2", a, t1 - t0, t2 - t1, t2 - t1, (double)total[0], ok);
    free(x);
    return ok ? 0 : 1;
}
